    faqTitle: "Frequently Asked Questions",
    faqSubtitle: "Find clear answers to common questions about emotional support animal evaluations, ESA documentation, and California housing laws.",
    faqs: [
      {
        q: "What is the cost of an ESA letter in California?",
        a: "If you pursue an ESA evaluation through our platform, the fee is $149. This covers the clinical evaluation, the legally required 30-day client-provider relationship, and ESA documentation if a recommendation is made. If an ESA is not determined to be clinically appropriate, no letter is issued, and any applicable refund is provided. Approval for an ESA is not guaranteed.",
      },
      {
        q: "Can I Get an ESA Letter Online in California?",
        a: "Yes. California allows ESA evaluations to be conducted via telehealth, provided the professional is licensed in California, conducts a proper clinical assessment, and maintains the required 30-day therapeutic relationship before issuing any recommendation.",
      },
      {
        q: "How long is an ESA letter valid in California?",
        a: "Although California law does not set a strict expiration date, most ESA letters are generally considered valid for 12 months. Many landlords and housing providers may request updated documentation annually.",
      },
      {
        q: "How Many ESAs Can I Have in California?",
        a: "In some cases, more than one emotional support animal may be recommended. Each animal must be individually assessed, and a licensed mental health professional must determine that each provides a distinct therapeutic benefit.",
      },
      {
        q: "What are the penalties for faking an ESA letter in California?",
        a: "Misrepresenting an emotional support animal or using fraudulent ESA documentation may lead to housing disputes, denied accommodations, fines, or legal consequences under state laws addressing disability fraud and misrepresentation.",
      },
      {
        q: "Can a landlord in California deny an ESA?",
        a: "California landlords may deny an ESA request in limited situations, such as insufficient documentation, undue financial burden, direct safety threats, or if the accommodation fundamentally changes housing operations.",
      },
      {
        q: "Can a landlord in California charge pet fees for an ESA?",
        a: "No. In California, landlords cannot charge pet rent or pet deposits for legitimate assistance animals under state housing protections.",
      },
      {
        q: "Does the 30-day rule mean I wait 30 days before I start the process?",
        a: "No. You can begin the process immediately. California's 30-day rule generally means a licensed provider must establish a relationship with you for at least 30 days before issuing an ESA letter recommendation.",
      },
      {
        q: "Does an ESA letter work for HOA housing and condos in California?",
        a: "Oftentimes, yes. HOAs and condo associations may still have reasonable accommodation obligations under California housing laws, even if pet restrictions exist. Accommodation requests are usually evaluated individually.",
      },
      {
        q: "Can a college or university in California deny an ESA in student housing?",
        a: "Schools may review ESA requests and deny accommodations in limited circumstances. However, colleges that provide housing often must still consider reasonable accommodation requests under housing-related disability laws.",
      },
      {
        q: "How long does a California landlord have to respond to an ESA accommodation request?",
        a: "California law does not provide a strict deadline, but housing providers are generally expected to respond to the accommodation request within a reasonable timeframe. Long delays or nonresponses may create legal issues. Under HUD guidance, responses are generally expected to be prompt, often within about 10 business days, though timelines may vary.",
      },
      {
        q: "Can I take my ESA on a plane in California?",
        a: "Usually, no. Federal airline rules no longer obligate airlines to treat emotional support animals as service animals, so most airlines now classify ESAs as pets subject to fees and carrier restrictions.",
      },
      {
        q: "Can I bring my ESA into a restaurant or store in California?",
        a: "Generally, no. Emotional support animals do not have the same public access rights as trained service animals, meaning restaurants, retail stores, and other businesses may legally restrict access. Emotional Support Animals do not have public access rights under the Americans with Disabilities Act (ADA).",
      },
      {
        q: "Can a California Landlord Require Proof of Training for My Emotional Support Animal?",
        a: "No. Emotional support animals are not required to have specialized training. However, the animal should be well-behaved, under control, and not pose a significant health, safety, or property damage risk. It may be beneficial to obtain training for your ESA to ensure they do not cause property damage, as you can be held liable for these repair fees.",
      },
      {
        q: "Can a child or minor get an ESA letter in California?",
        a: "Yes. Minors in California may qualify for an ESA letter if a licensed mental health professional determines that the animal supports the child's mental or emotional health needs. Parents or legal guardians are typically involved in the evaluation and housing accommodation process, and often must sign consents before the evaluation can proceed.",
      },
      {
        q: "Can I get an ESA letter the same day in California?",
        a: "No. California's 30-day provider relationship requirement generally prevents legitimate providers from issuing same-day ESA letters. Most legal ESA evaluations require time to establish a provider-client relationship before documentation can be issued.",
      },
      {
        q: "If I move to a new apartment in California, do I need a new ESA letter?",
        a: "Usually no, but your new landlord may request updated documentation during the accommodation review process. Keeping your ESA letter up to date can help avoid delays when moving into new housing.",
      },
      {
        q: "Does my emotional support animal need rabies vaccination or local licensing in California?",
        a: "Yes. Emotional support animals must comply with the same local animal health and licensing requirements as other pets, including rabies vaccinations where required by state or local law.",
      },
      {
        q: "Does my ESA need to wear a vest or tag in California?",
        a: "No. California does not require emotional support animals to wear vests, ID cards, tags, or special markings. Housing rights are generally based on documentation, not accessories or registration products.",
      },
      {
        q: "Can a California Landlord Ask My Therapist Directly to Verify the ESA Letter?",
        a: "In some cases, a landlord may seek to verify that the letter was issued by a licensed mental health professional. However, they generally cannot request detailed medical information or access to your treatment records. They cannot request the specific diagnosis to be disclosed, nor the severity of your disability.",
      },
    ],
