    lawsTitle: "Understanding Your ESA Housing Rights in Montana",
    lawsSubtitle: "In Montana, emotional support animal accommodations are governed by House Bill 703 and federal fair housing laws. Both landlords and tenants must follow these regulations when requesting or reviewing an ESA accommodation.",
